import { Schema } from "effect";
import { EmailAddress } from "../email/Email.ts";
import { PersonId } from "../people/Identity.ts";
import { TeamId } from "../people/Team.ts";
import { Dimension } from "../pulses/Question.ts";
import { RoundId } from "../rounds/Round.ts";

/** An Action committed by a Team in response to a Result (GLOSSARY.md). */
export const ActionId = Schema.String.pipe(Schema.brand("ActionId"));
export type ActionId = typeof ActionId.Type;

/**
 * Statuses an Action can have.
 * Release 1 uses `committed`, `done`, and `dropped`. `proposed` is modelled but unused in R1.
 */
export const ActionStatus = Schema.Literals(["proposed", "committed", "done", "dropped"]);
export type ActionStatus = typeof ActionStatus.Type;

/** Internal stored Action record in the DO sqlite database. */
export const ActionRecord = Schema.Struct({
  id: ActionId,
  teamId: TeamId,
  roundId: RoundId,
  title: Schema.NonEmptyString,
  ownerId: PersonId,
  dueDate: Schema.NullOr(Schema.String),
  dimension: Schema.NullOr(Dimension),
  status: ActionStatus,
  createdAt: Schema.Int,
  updatedAt: Schema.Int,
  doneAt: Schema.NullOr(Schema.Int),
});
export type ActionRecord = typeof ActionRecord.Type;

/** An Action as viewed by the team or API callers, including the owner's email address. */
export const ActionItem = Schema.Struct({
  id: ActionId,
  teamId: TeamId,
  roundId: RoundId,
  title: Schema.String,
  ownerId: PersonId,
  ownerEmail: EmailAddress,
  dueDate: Schema.NullOr(Schema.String),
  dimension: Schema.NullOr(Dimension),
  status: ActionStatus,
  createdAt: Schema.Int,
  updatedAt: Schema.Int,
  doneAt: Schema.NullOr(Schema.Int),
});
export type ActionItem = typeof ActionItem.Type;

/** The list of Actions for a Team. Actions have no minimum group size. */
export const ActionList = Schema.Struct({
  teamId: TeamId,
  actions: Schema.Array(ActionItem),
});
export type ActionList = typeof ActionList.Type;

/** Payload to create an Action from a Result. */
export const CreateAction = Schema.Struct({
  roundId: RoundId,
  title: Schema.NonEmptyString,
  ownerId: PersonId,
  dueDate: Schema.NullOr(Schema.String),
  dimension: Schema.NullOr(Dimension),
});
export type CreateAction = typeof CreateAction.Type;

/** Payload to update an Action. */
export const UpdateAction = Schema.Struct({
  title: Schema.optional(Schema.NonEmptyString),
  ownerId: Schema.optional(PersonId),
  dueDate: Schema.optional(Schema.NullOr(Schema.String)),
  dimension: Schema.optional(Schema.NullOr(Dimension)),
  status: Schema.optional(ActionStatus),
});
export type UpdateAction = typeof UpdateAction.Type;

export class ActionNotFound extends Schema.TaggedError<ActionNotFound, { readonly brand: unique symbol }>()(
  "ActionNotFound",
  {},
  { httpApiStatus: 404 },
) {}

export class OwnerNotInTeam extends Schema.TaggedError<OwnerNotInTeam, { readonly brand: unique symbol }>()(
  "OwnerNotInTeam",
  {},
  { httpApiStatus: 400 },
) {}

export interface ActionSelectionInput {
  readonly id: ActionId | string;
  readonly title: string;
  readonly status: ActionStatus;
  readonly createdAt: number;
  readonly updatedAt: number;
  readonly doneAt: number | null;
}

export interface PreviousRoundInfo {
  readonly openedAt: number | null;
  readonly plannedOpenAt: number;
}

/**
 * Selects up to three Actions to show on the next Invitation email and the thank-you screen:
 * those still committed, plus those marked done since the previous Round.
 * Excludes proposed and dropped actions.
 * Actions list has no minimum group size.
 */
export const selectActionsForRound = <A extends ActionSelectionInput>(
  actions: ReadonlyArray<A>,
  previousRound: PreviousRoundInfo | null,
): ReadonlyArray<A> => {
  const previousCutoff = previousRound ? (previousRound.openedAt ?? previousRound.plannedOpenAt) : 0;
  return actions
    .filter((action) => {
      if (action.status === "committed") return true;
      if (action.status === "done" && action.doneAt !== null) {
        return previousRound !== null ? action.doneAt >= previousCutoff : false;
      }
      return false;
    })
    .slice(0, 3);
};
import { Clock, Context, Effect } from "effect";
import type { PersonId } from "../people/Identity.ts";
import type { OrganizationId } from "../people/Organization.ts";
import { Forbidden } from "../people/SignIn.ts";
import type { Member } from "../people/SignInFlow.ts";
import { PersonNotFound, type TeamId, TeamNotFound } from "../people/Team.ts";
import { RoundNotFound } from "../rounds/Round.ts";
import {
  type ActionId,
  type ActionItem,
  type ActionList,
  ActionNotFound,
  type CreateAction,
  OwnerNotInTeam,
  type UpdateAction,
} from "./Action.ts";

export type ActionRejection =
  | { readonly _tag: "Forbidden" }
  | { readonly _tag: "TeamNotFound" }
  | { readonly _tag: "RoundNotFound" }
  | { readonly _tag: "ActionNotFound" }
  | { readonly _tag: "OwnerNotInTeam" }
  | { readonly _tag: "PersonNotFound" };

export type ActionViewed<A> =
  | { readonly _tag: "Viewed"; readonly value: A }
  | { readonly _tag: "Rejected"; readonly rejection: ActionRejection };

export interface OrganizationActionsShape {
  readonly list: (
    organizationId: OrganizationId,
    actorId: PersonId,
    teamId: TeamId,
  ) => Effect.Effect<ActionViewed<ActionList>>;
  readonly create: (
    organizationId: OrganizationId,
    actorId: PersonId,
    teamId: TeamId,
    payload: CreateAction,
    now: number,
  ) => Effect.Effect<ActionViewed<ActionItem>>;
  readonly update: (
    organizationId: OrganizationId,
    actorId: PersonId,
    teamId: TeamId,
    actionId: ActionId,
    payload: UpdateAction,
    now: number,
  ) => Effect.Effect<ActionViewed<ActionItem>>;
}

export class OrganizationActions extends Context.Service<OrganizationActions, OrganizationActionsShape>()(
  "@surveybeat/domain/OrganizationActions",
) {}

export type ActionError =
  | Forbidden
  | TeamNotFound
  | RoundNotFound
  | ActionNotFound
  | OwnerNotInTeam
  | PersonNotFound;

const mapRejection = (rejection: ActionRejection): ActionError => {
  switch (rejection._tag) {
    case "Forbidden":
      return new Forbidden();
    case "TeamNotFound":
      return new TeamNotFound();
    case "RoundNotFound":
      return new RoundNotFound();
    case "ActionNotFound":
      return new ActionNotFound();
    case "OwnerNotInTeam":
      return new OwnerNotInTeam();
    case "PersonNotFound":
      return new PersonNotFound();
  }
};

const unwrap = <A>(result: ActionViewed<A>): Effect.Effect<A, ActionError> =>
  result._tag === "Viewed" ? Effect.succeed(result.value) : Effect.fail(mapRejection(result.rejection));

export const listActions = (
  member: Member,
  teamId: TeamId,
): Effect.Effect<ActionList, ActionError, OrganizationActions> =>
  Effect.flatMap(OrganizationActions, (actions) =>
    actions.list(member.organization.id, member.personId, teamId).pipe(Effect.flatMap(unwrap)),
  );

export const createAction = (
  member: Member,
  teamId: TeamId,
  payload: CreateAction,
): Effect.Effect<ActionItem, ActionError, OrganizationActions> =>
  Effect.gen(function* () {
    const actions = yield* OrganizationActions;
    const now = yield* Clock.currentTimeMillis;
    const result = yield* actions.create(member.organization.id, member.personId, teamId, payload, now);
    return yield* unwrap(result);
  });

export const updateAction = (
  member: Member,
  teamId: TeamId,
  actionId: ActionId,
  payload: UpdateAction,
): Effect.Effect<ActionItem, ActionError, OrganizationActions> =>
  Effect.gen(function* () {
    const actions = yield* OrganizationActions;
    const now = yield* Clock.currentTimeMillis;
    const result = yield* actions.update(
      member.organization.id,
      member.personId,
      teamId,
      actionId,
      payload,
      now,
    );
    return yield* unwrap(result);
  });
