  member: Member,
  teamId: TeamId,
  roundId: RoundId,
  payload: SaveNote,
): Effect.Effect<RoundNoteView, NoteError, OrganizationNotes> =>
  Effect.gen(function* () {
    const notes = yield* OrganizationNotes;
    const now = yield* Clock.currentTimeMillis;
    const result = yield* notes.save(member.organization.id, member.personId, teamId, roundId, payload.text, now);
    return yield* unwrap(result);
  });
